public void init()
{
    QueryBuildDataSource    qbds;
    Common                  callerRecord;

    next init();

    qbds = this.queryBuildDataSource();
    callerRecord = this.formRun().args().record();

    if (callerRecord && qbds)
    {
        qbds.addOrderByField(fieldNum(BatchHistory, StartDateTime), SortOrder::Descending);
    }
}
